  ADD UNIQUE KEY `vf57_state_reminder_log` (`reminder_delivery_log_id`),
  ADD CONSTRAINT `vf57_state_reminder_log_fk` FOREIGN KEY (`reminder_delivery_log_id`) REFERENCES `notification_delivery_log` (`id`) ON UPDATE RESTRICT ON DELETE RESTRICT;

